    21	/**
    22	 * Immutable structured audit event emitted on a successful owner create, alongside the human-readable
    23	 * audit line. Serialized to JSON as {@code {seq, ownerId, customerCode, membershipLevel, event}}.
    24	 *
    25	 * <p>{@code seq} is a monotonically increasing sequence number across creates. The
    26	 * {@code primaryIdentifier} component carries the owner's <em>current primary identifier</em> (see
    27	 * {@link org.springframework.samples.petclinic.model.Owner#getPrimaryIdentifier()}): today the
    28	 * customerCode, and whatever replaces it later — so when the customerCode is unified into the
    29	 * memberId it automatically carries the memberId instead, with no change here. The component is named
    30	 * for what it holds, while its JSON key is pinned to {@code customerCode} to preserve the wire
    31	 * contract.
    32	 */
    33	public record OwnerCreatedEvent(long seq, Integer ownerId,
    34	                                @JsonProperty("customerCode") String primaryIdentifier,
    35	                                int membershipLevel, String event) {
    36	
    37	    /** The fixed {@code event} discriminator carried by every owner-created event. */
    38	    public static final String EVENT_TYPE = "OWNER_CREATED";
